const zamowienia = [
  { id: 1, produkty: ["chleb", "mleko"] },
  { id: 2, produkty: ["maslo"] }
];

const wszystkieProdukty = zamowienia.flatMap(z => z.produkty);
console.log(wszystkieProdukty); // ['chleb', 'mleko', 'maslo']

