const zdania = ["Ala ma kota", "Kot ma Ale"];
const wynik = zdania.flatMap(z => z.split(" "));
console.log(wynik); // ['Ala', 'ma', 'kota', 'Kot', 'ma', 'Ale']

const koszyki = [
  { klient: "Ala", produkty: ["ksiazka", "dlugopis"] },
  { klient: "Bartek", produkty: ["zeszyt"] }
];

const opisy = koszyki.flatMap(k =>
  k.produkty.map(p => `${k.klient}: ${p}`)
);

console.log(opisy);
// ['Ala: ksiazka', 'Ala: dlugopis', 'Bartek: zeszyt']
